const fs=require("fs");
function sig(d){ if(!d) return ""; let t=Array.isArray(d.type)?d.type.join("|"):(d.type||(d.enum?"enum":"")); let s=t; if(d.maxLength!=null) s+=":"+d.maxLength; if(d.minimum!=null) s+=">"+d.minimum; if(d.maximum!=null) s+="<"+d.maximum; return s;}
function lvl(props){ const o={}; for(const [k,d] of Object.entries(props)){ if(d.type==="array"&&d.items&&d.items.properties) o[k]={s:sig(d),p:lvl(d.items.properties)}; else o[k]=sig(d);} return o;}
const out={};
for(const f of fs.readdirSync("api")){ const j=JSON.parse(fs.readFileSync("api/"+f)); for(const [op,d] of Object.entries(j.ops)){ if(op==="status")continue; out[j.system+"."+op]=lvl(d.args.properties);} for(const [t,d] of Object.entries(j.tables)) out["T:"+j.system+"."+t]=Object.fromEntries(Object.entries(d.fields).map(([k,v])=>[k,sig(v)])); }
console.log(JSON.stringify(out));
'

