    k: 'order', v: 1, oid,
    cust: o.cust, p: o.p, pm, cur: o.cur, items: o.items,
    ed: null, pol: {}, email: null,
    alloc: null, rd: {}, fraud: null, fraudAt: null,
    cleared: null, rev: null, acts: [], counted: null, stop: null,
    ready: null, os: null, F: {}, E: {}, N: {}, T: {}, H: {}, ren: {}, seen: [],
