}
const hasUn = (S) => !!(S.alloc && S.alloc.some((f) => !f.av));
const hasAv = (S) => !!(S.alloc && S.alloc.some((f) => f.av));
const TERM_F = new Set(['completed', 'cancelled', 'failed']);
const TERM_O = new Set(['completed', 'cancelled', 'failed', 'timedOut']);
