  if (acc.fulfilments.length) {
    setAlloc(R, acc.fulfilments.map((f) => ({
      fulfilmentId: f.fulfilmentId, location: f.location, items: f.items, amountMinor: f.amountMinor,
      available: f.location != null && f.status !== 'unavailable',
