// Minimal mock of the bed host for E8, for local testing only.
import * as fs from 'node:fs';
import * as path from 'node:path';

const MIN = 60000;
export const T = (s) => Date.parse(s);
function iso(t) { // Amsterdam winter/summer approx for tests
  const d = new Date(t); const y = d.getUTCFullYear();
  const ls = (m) => { const l = new Date(Date.UTC(y, m + 1, 0)); return Date.UTC(y, m, l.getUTCDate() - l.getUTCDay()); };
  const off = t >= ls(2) + 3600e3 && t < ls(9) + 3600e3 ? 120 : 60;
  return new Date(t + off * MIN).toISOString().slice(0, 19) + (off === 120 ? '+02:00' : '+01:00');
}
export { iso };

export function makeFiles(apiDir, extra = {}) {
  const files = {};
  for (const f of fs.readdirSync(apiDir)) files['api/' + f] = fs.readFileSync(path.join(apiDir, f), 'utf8');
  files['master/catalog.json'] = JSON.stringify([{ sku: 'A', unitPriceMinor: 1000 }, { sku: 'B', unitPriceMinor: 250 }, { sku: 'C', unitPriceMinor: 99 }]);
  files['master/customers.json'] = JSON.stringify([{ customerId: 'C1', email: 'c1@example.com' }]);
  files['master/locations.json'] = JSON.stringify([{ location: 'AMS', collectionTime: '17:00' }, { location: 'RTM', collectionTime: '16:00' }]);
  files['calendar/cal-warehouse.json'] = JSON.stringify({ id: 'cal-warehouse', tz: 'Europe/Amsterdam' });
  files['rulebook/E1/edition.json'] = JSON.stringify({ id: 'E1', effectiveFrom: '2026-01-01' });
  files['rulebook/E1/policy.json'] = JSON.stringify({ fraudReviewHours: 4, customerActionHours: 24, collectionCutoffMinutes: 30 });
  files['rulebook/E1/shipping-fees.json'] = JSON.stringify({ AMS: { feeMinor: 495 }, RTM: { feeMinor: 395 } });
  files['rulebook/E1/carrier-codes.json'] = JSON.stringify({ PostNL: { PU: 'collected', TR: 'inTransit', DL: 'delivered', XF: 'collectionFailed', NT: 'info' } });
  files['rulebook/E2/edition.json'] = JSON.stringify({ id: 'E2', effectiveFrom: '2026-12-01' });
  files['rulebook/E2/policy.json'] = JSON.stringify({ fraudReviewHours: 99, customerActionHours: 99, collectionCutoffMinutes: 30 });
  files['rulebook/E2/shipping-fees.json'] = JSON.stringify({ AMS: { feeMinor: 9999 } });
  Object.assign(files, extra);
  return files;
}

export class Host {
  constructor({ solver, files, plan = {}, readMode = 'effect', log = false }) {
    this.solver = solver; this.files = files; this.plan = plan; this.readMode = readMode; this.log = log;
    this.tables = { 'orders.orders': [], 'orders.fulfilments': [], 'inventory.reservations': [], 'billing.charges': [], 'billing.refunds': [], 'carrier.shipments': [], 'notify.notifications': [] };
    this.keys = {}; // system -> key -> {args, result}
    this.instances = {}; // id -> {carry, subject, open, openedAt}
    this.queue = []; // {at, inst|null, ev}
    this.ledger = [];
    this.tasks = [];
    this.obl = {}; // inst -> id -> {dueAt}
    this.seq = 0; this.errors = [];
    this.outputs = [];
  }
  newInstance(now) { const id = 'i-' + String(++this.seq).padStart(6, '0'); this.instances[id] = { carry: null, subject: null, open: true, openedAt: iso(now) }; return id; }
  push(at, inst, ev) { ev.id = ev.id || 'e' + (++this.seq); ev.at = ev.at || iso(at); this.queue.push({ at, inst, ev }); }
  inbound(at, type, payload, source) { this.push(at, null, { type, source, channel: { kind: 'inbound' }, payload }); }
  migration(at, payload) { const id = this.newInstance(at); this.push(at, id, { type: 'migration', channel: { kind: 'instance', instance: id }, payload }); return id; }
  ctx(inst) {
    const self = this;
    return {
      files: this.files,
      query(table, { where = {}, limit = 1000 } = {}) {
        const rows = self.tables[table];
        if (!rows) throw new Error('unknown table ' + table);
        return rows.filter((r) => Object.entries(where).every(([k, v]) => (isObj(v) ? true : r[k] === v))).slice(0, limit).map((r) => JSON.parse(JSON.stringify(r)));
      },
      status(system, key) { const k = self.keys[system] && self.keys[system][key]; return k ? (k.pending ? 'pending' : 'committed') : 'not-found'; },
      instances({ subject }) { return Object.entries(self.instances).filter(([, v]) => v.open && v.subject === subject).map(([id, v]) => ({ instance: id, subject: v.subject, openedAt: v.openedAt })); },
      ...(this.readMode === 'call' ? { call: (s, o, a) => self.read(s, o, a) } : {}),
    };
  }
  read(sys, op, args) {
    if (op === 'allocate') return this.plan.alloc(args.orderId);
    if (op === 'check') return { orderId: args.orderId, verdict: (this.plan.fraud && this.plan.fraud[args.orderId]) || 'pass' };
  }
  run(until) {
    for (let guard = 0; guard < 5000; guard++) {
      const due = [];
      for (const [inst, m] of Object.entries(this.obl)) for (const [id, o] of Object.entries(m)) due.push({ at: T(o.dueAt), inst, id, onDue: o.onDue });
      const nextQ = Math.min(...this.queue.map((q) => q.at), ...due.map((d) => d.at));
      if (!Number.isFinite(nextQ) || nextQ > until) return;
      const now = nextQ;
      for (const d of due) if (d.at === now) { delete this.obl[d.inst][d.id]; this.push(now, d.inst, { type: 'timer.fired', channel: { kind: 'instance', instance: d.inst }, payload: { obligationId: d.id, onDue: d.onDue } }); }
      const batch = this.queue.filter((q) => q.at === now); this.queue = this.queue.filter((q) => q.at !== now);
      // route
      const per = {};
      for (const q of batch) {
        let inst = q.inst;
        if (!inst) {
          // carrier ref routing
          const ref = q.ev.payload && q.ev.payload.ref;
          const owner = ref && Object.entries(this.instances).find(([, v]) => v.open && v.refs && v.refs.includes(ref));
          if (owner) inst = owner[0]; else inst = this.newInstance(now);
        }
        if (!this.instances[inst].open) continue;
        (per[inst] = per[inst] || []).push(q.ev);
      }
      for (const [inst, evs] of Object.entries(per)) this.tickInst(inst, now, evs);
    }
  }
  tickInst(inst, now, events) {
    const I = this.instances[inst];
    const input = { kind: 'case', item: 'e8', world: 'w1', instance: inst, now: iso(now), events, carry: I.carry };
    const out = this.solver.tick(JSON.parse(JSON.stringify(input)), this.ctx(inst));
    this.outputs.push({ inst, now: iso(now), events: events.map((e) => e.type + (e.payload && (e.payload.op ? ':' + e.payload.op + ':' + e.payload.status : e.payload.action ? ':' + e.payload.action : e.payload.code ? ':' + e.payload.code : e.payload.onDue ? ':' + e.payload.onDue : ''))), out });
    if (this.log) console.log(iso(now), inst, events.map((e) => e.type).join(','), JSON.stringify(out.effects.map((e) => `${e.system}.${e.op}${e.after ? '(after)' : ''} ${e.args.status || e.args.template || ''}`)), out.close ? 'CLOSE' : '', out.merge ? 'MERGE->' + out.merge.into : '');
    const sz = JSON.stringify(out.carry).length; if (sz > 64000) this.errors.push('carry too big ' + sz);
    if (!out.decisions || !('subject' in out.decisions)) this.errors.push('no subject');
    I.carry = out.carry; I.subject = out.decisions.subject;
    for (const h of out.humanTasks || []) { this.tasks.push({ inst, at: now, ...h }); if (this.plan.onTask) this.plan.onTask(this, inst, now, h); }
    const ob = this.obl[inst] = this.obl[inst] || {};
    for (const id of out.obligations.cancel) delete ob[id];
    for (const u of out.obligations.upsert) { ob[u.id] = { dueAt: T(u.dueAt) <= now ? iso(now + MIN) : u.dueAt, onDue: u.onDue }; }
    const results = {};
    for (const eff of out.effects) {
      if (eff.after && !(results[eff.after] && results[eff.after].status === 'ok')) {
        const r = { key: eff.key, system: eff.system, op: eff.op, status: 'error', error: { code: 'predecessor-failed' } };
        results[eff.key] = r; this.push(now + MIN, inst, { type: 'effect.result', channel: { kind: 'instance', instance: inst }, payload: r });
        continue;
      }
      const r = this.apply(inst, now, eff);
      results[eff.key || eff.system + eff.op] = r;
      this.push(now + (r.lat || 1) * MIN, inst, { type: 'effect.result', channel: { kind: 'instance', instance: inst }, payload: Object.assign({ key: eff.key, system: eff.system, op: eff.op }, r, { lat: undefined }) });
    }
    if (out.merge) { I.open = false; for (const ev of events) this.tickInst(out.merge.into, now, [ev]); }
    else if (out.close) I.open = false;
  }
  apply(inst, now, eff) {
    const { system, op, args, key } = eff;
    const schema = JSON.parse(this.files[`api/${system}.schema.json`]);
    const os = schema.ops[op];
    if (!os) { this.errors.push('unknown op ' + system + '.' + op); return { status: 'error', error: { code: 400 } }; }
    // field validation (top-level)
    for (const r of os.args.required || []) if (!(r in args)) return { status: 'error', error: { code: 400, reason: 'field-renamed', field: r } };
    for (const k of Object.keys(args)) if (!(k in os.args.properties)) return { status: 'error', error: { code: 400, reason: 'invalid-args', field: k } };
    if (os.readOnly) {
      const d = this.read(system, op, args);
      return { status: 'ok', result: d };
    }
    if (os.keyed && !os.batch) {
      const ks = (this.keys[system] = this.keys[system] || {});
      if (ks[key]) { if (JSON.stringify(ks[key].args) !== JSON.stringify(args)) return { status: 'error', error: { code: 409, reason: 'key-conflict' } }; return ks[key].result; }
    }
    this.ledger.push({ at: iso(now), inst, system, op, key, args });
    const fault = this.plan.fault && this.plan.fault(this, eff, now);
    if (fault) { if (fault.commit) { this.keys[system] = this.keys[system] || {}; this.keys[system][key] = { args, result: { status: 'ok' } }; this.applyBiz(now, eff); } return fault.result; }
    if (os.batch) {
      const items = args.items.map((it) => {
        const ks = (this.keys[system] = this.keys[system] || {});
        if (ks[it.key]) return { key: it.key, status: 'ok' };
        const f = this.plan.reserveFail && this.plan.reserveFail(this, args, it);
        if (f) return { key: it.key, status: 'error', error: f };
        ks[it.key] = { args: it, result: { status: 'ok' } };
        this.tables['inventory.reservations'].push({ reservationId: 'R' + (++this.seq), orderId: args.orderId, fulfilmentId: args.fulfilmentId, location: args.location, sku: it.sku, qty: it.qty, status: 'active', at: iso(now) });
        return { key: it.key, status: 'ok' };
      });
      const st = items.every((i) => i.status === 'ok') ? 'ok' : items.some((i) => i.status === 'ok') ? 'partial' : 'error';
      return { status: st, items };
    }
    if (system === 'billing' && op === 'charge' && this.plan.decline && this.plan.decline(args)) return { status: 'error', error: { code: 402, reason: 'card-declined', retryable: false } };
    if (system === 'carrier' && op === 'cancel') {
      const sh = this.tables['carrier.shipments'].find((s) => s.fulfilmentId === args.fulfilmentId && s.status !== 'cancelled');
      if (sh && sh.status !== 'created') return { status: 'error', error: { code: 409, reason: 'already-collected', retryable: false } };
    }
    const res = { status: 'ok' };
    this.keys[system] = this.keys[system] || {}; this.keys[system][key] = { args, result: res };
    this.applyBiz(now, eff, inst);
    return res;
  }
  applyBiz(now, { system, op, args }, inst) {
    const t = this.tables;
    if (system === 'orders' && op === 'create') {
      t['orders.orders'].push({ orderId: args.orderId, customerId: args.customerId, status: 'pending', placedAt: args.placedAt, currency: args.currency, items: args.items, totalMinor: args.totalMinor });
      for (const f of args.fulfilments) t['orders.fulfilments'].push({ ...f, orderId: args.orderId, status: f.location == null ? 'unavailable' : 'pending' });
    } else if (system === 'orders' && op === 'setStatus') {
      if (args.fulfilmentId == null) t['orders.orders'].find((o) => o.orderId === args.orderId).status = args.status;
      else t['orders.fulfilments'].find((o) => o.fulfilmentId === args.fulfilmentId).status = args.status;
    } else if (system === 'billing' && op === 'charge') t['billing.charges'].push({ chargeId: 'CH' + (++this.seq), ...args, at: iso(now), refundedMinor: 0 });
    else if (system === 'billing' && op === 'refund') { t['billing.refunds'].push({ refundId: 'RF' + (++this.seq), ...args, at: iso(now) }); const c = t['billing.charges'].find((c) => c.fulfilmentId === args.fulfilmentId); if (c) c.refundedMinor += args.amountMinor; }
    else if (system === 'inventory' && op === 'release') { const r = t['inventory.reservations'].find((r) => r.fulfilmentId === args.fulfilmentId && r.sku === args.sku && r.status === 'active'); if (r) r.status = 'released'; else this.errors.push('release without reservation ' + args.sku); }
    else if (system === 'carrier' && op === 'create') {
      const sid = 'SH' + (++this.seq);
      t['carrier.shipments'].push({ shipmentId: sid, orderId: args.orderId, fulfilmentId: args.fulfilmentId, location: args.location, carrier: 'PostNL', status: 'created', createdAt: iso(now), ref: args.ref ?? null });
      if (inst) { const I = this.instances[inst]; I.refs = (I.refs || []).concat(args.ref); }
      if (this.plan.onShip) this.plan.onShip(this, args, now, sid);
    } else if (system === 'carrier' && op === 'cancel') { const sh = t['carrier.shipments'].find((s) => s.fulfilmentId === args.fulfilmentId); if (sh) sh.status = 'cancelled'; }
    else if (system === 'notify' && op === 'send') t['notify.notifications'].push({ notificationId: 'N' + (++this.seq), ...args, sentAt: iso(now) });
  }
  carrierMsg(at, args, code, extra = {}) {
    this.inbound(at, 'message.received', { ref: args.ref, carrier: 'PostNL', code, shipmentId: extra.sid || 'x', fulfilmentRef: args.fulfilmentId, reportedAt: iso(extra.reportedAt ?? at) }, 'carrier');
    const sh = this.tables['carrier.shipments'].find((s) => s.fulfilmentId === args.fulfilmentId);
    if (sh && sh.status !== 'cancelled') sh.status = { PU: 'collected', TR: 'inTransit', DL: 'delivered', XF: 'failed' }[code] || sh.status;
  }
  summary() {
    return this.ledger.map((l) => `${l.at} ${l.system}.${l.op} ${l.args.fulfilmentId ?? ''} ${l.args.status ?? l.args.template ?? (l.args.items ? l.args.items.map((i) => i.sku).join('+') : '') ?? ''} ${l.args.amountMinor ?? ''}`.replace(/\s+/g, ' ').trim());
  }
}
const isObj = (x) => x && typeof x === 'object' && !Array.isArray(x);

