      if (sh && sh.status !== 'created') return { status: 'error', error: { code: 409, reason: 'already-collected', retryable: false } };
    }
    const res = { status: 'ok' };
    this.keys[system] = this.keys[system] || {}; this.keys[system][key] = { args, result: res };
    this.applyBiz(now, eff, inst);
    return res;
  }
  applyBiz(now, { system, op, args }, inst) {
