import { Host, makeFiles, T, iso } from './host.mjs';
import { createSolver } from '../b1o-e8-1/solver.mjs';

const API = new URL('../b1o-e8-1/api', import.meta.url).pathname;
const P = T('2026-10-14T10:00:00+02:00');
const MIN = 60000, H = 3600000;

function alloc2(oid) {
  return { orderId: oid, fulfilments: [
    { fulfilmentId: oid + '-F1', location: 'AMS', items: [{ sku: 'A', qty: 2 }, { sku: 'C', qty: 1 }], available: true },
    { fulfilmentId: oid + '-F2', location: 'RTM', items: [{ sku: 'B', qty: 1 }], available: true },
  ] };
}
function allocUn(oid, allUn = false) {
  return { orderId: oid, fulfilments: [
    ...(allUn ? [] : [{ fulfilmentId: oid + '-F1', location: 'AMS', items: [{ sku: 'A', qty: 1 }], available: true }]),
    { fulfilmentId: oid + '-F9', location: null, items: [{ sku: 'B', qty: 3 }], available: false },
  ] };
}
function place(h, at, raw, items = [{ sku: 'A', qty: 2 }, { sku: 'C', qty: 1 }, { sku: 'B', qty: 1 }]) {
  h.inbound(at, 'message.received', { orderId: raw, customerId: 'C1', placedAt: iso(at), currency: 'EUR', items, channel: 'web' }, 'shop');
}
function action(h, at, ref, act) { h.inbound(at, 'message.received', { orderRef: ref, action: act, from: 'c1@example.com' }, 'customer-portal'); }
function deliverAll(h, args, now, sid, { pu = 60, dl = 300, swap = false } = {}) {
  if (swap) { h.carrierMsg(now + dl * MIN, args, 'DL', { sid }); h.carrierMsg(now + (dl + 5) * MIN, args, 'PU', { sid, reportedAt: now + pu * MIN }); }
  else { h.carrierMsg(now + pu * MIN, args, 'PU', { sid }); h.carrierMsg(now + (pu + 30) * MIN, args, 'TR', { sid }); h.carrierMsg(now + dl * MIN, args, 'DL', { sid }); }
}

function scenario(name, plan, setup, { readMode = 'effect', until = P + 72 * H, files } = {}) {
  const h = new Host({ solver: createSolver(), files: files || makeFiles(API), plan, readMode, log: process.env.LOG === name });
  setup(h);
  h.run(until);
  console.log('=== ' + name);
  for (const l of h.summary()) console.log('  ' + l);
  const o = h.tables['orders.orders'];
  console.log('  orders:', o.map((x) => x.orderId + ':' + x.status).join(' '), '| fuls:', h.tables['orders.fulfilments'].map((f) => f.fulfilmentId.split('-').pop() + ':' + f.status).join(' '));
  console.log('  open:', Object.entries(h.instances).filter(([, v]) => v.open).map(([k, v]) => k + '(' + v.subject + ')').join(' ') || '-', ' tasks:', h.tasks.length, h.errors.length ? ' ERRORS: ' + h.errors.join('; ') : '');
  return h;
}

const which = process.argv[2];
const S = {};

S.happy = () => scenario('happy', { alloc: alloc2, onShip: (h, a, now, sid) => deliverAll(h, a, now, sid, { swap: a.fulfilmentId.endsWith('F2') }) }, (h) => {
  place(h, P, ' #ord-1001-0007');
  place(h, P + 30 * MIN, 'ORD-1001-0007'); // duplicate
  action(h, P + 10 * H, 'ord-9999', 'cancel'); // unknown order
});
S.happyCall = () => scenario('happyCall', { alloc: alloc2, onShip: (h, a, now, sid) => deliverAll(h, a, now, sid) }, (h) => place(h, P, 'ORD-2'), { readMode: 'call' });

S.reviewApprove = () => scenario('reviewApprove', { alloc: alloc2, fraud: { 'ORD-3': 'review' }, onShip: (h, a, now, sid) => deliverAll(h, a, now, sid),
  onTask: (h, inst, now, t) => h.push(now + 30 * MIN, inst, { type: 'humanTask.answered', payload: { taskId: t.id, answer: { decision: 'approve' } } }) }, (h) => place(h, P, 'ORD-3'));
S.reviewReask = () => scenario('reviewReask', { alloc: alloc2, fraud: { 'ORD-3': 'review' }, onShip: (h, a, now, sid) => deliverAll(h, a, now, sid),
  onTask: (h, inst, now, t) => h.push(now + 30 * MIN, inst, { type: t.id.endsWith('-1') ? 'humanTask.withdrawn' : 'humanTask.answered', payload: { taskId: t.id, answer: { decision: 'reject' } } }) }, (h) => place(h, P, 'ORD-3'));
S.reviewTimeout = () => scenario('reviewTimeout', { alloc: alloc2, fraud: { 'ORD-4': 'review' },
  onTask: (h, inst, now, t) => h.push(T(t.dueAt), inst, { type: 'humanTask.timeout', payload: { taskId: t.id } }) }, (h) => place(h, P, 'ORD-4'));
S.reviewCancel = () => scenario('reviewCancel', { alloc: alloc2, fraud: { 'ORD-4': 'review' } }, (h) => { place(h, P, 'ORD-4'); action(h, P + 60 * MIN, 'ord-4', 'cancel'); });
S.reject = () => scenario('reject', { alloc: alloc2, fraud: { 'ORD-5': 'reject' } }, (h) => place(h, P, 'ORD-5'));

S.amend = () => scenario('amend', { alloc: (o) => allocUn(o), onShip: (h, a, now, sid) => deliverAll(h, a, now, sid) }, (h) => { place(h, P, 'ORD-6'); action(h, P + 3 * H, 'ord-6', 'amend'); action(h, P + 4 * H, 'ord-6', 'amend'); });
S.amendAll = () => scenario('amendAllUn', { alloc: (o) => allocUn(o, true) }, (h) => { place(h, P, 'ORD-7'); action(h, P + 3 * H, 'ORD-7', 'amend'); });
S.waitCancel = () => scenario('waitCancel', { alloc: (o) => allocUn(o) }, (h) => { place(h, P, 'ORD-8'); action(h, P + 24 * H, 'ORD-8', 'cancel'); });
S.timeout = () => scenario('timeout', { alloc: (o) => allocUn(o) }, (h) => { place(h, P, 'ORD-9'); action(h, P + 24 * H + MIN, 'ORD-9', 'amend'); });

S.declined = () => scenario('declined', { alloc: alloc2, decline: (a) => a.fulfilmentId.endsWith('F1'), onShip: (h, a, now, sid) => deliverAll(h, a, now, sid) }, (h) => place(h, P, 'ORD-10'));
S.collFail = () => scenario('collFail', { alloc: alloc2, onShip: (h, a, now, sid) => (a.fulfilmentId.endsWith('F1') ? h.carrierMsg(now + 60 * MIN, a, 'XF', { sid }) : deliverAll(h, a, now, sid)) }, (h) => place(h, P, 'ORD-11'));
S.cancelProc = () => scenario('cancelProc', { alloc: alloc2 }, (h) => { place(h, P, 'ORD-12'); action(h, P + 4 * MIN, 'ORD-12', 'cancel'); });
S.cancelShipped = () => scenario('cancelShipped', { alloc: alloc2, onShip: (h, a, now, sid) => { if (a.fulfilmentId.endsWith('F2')) deliverAll(h, a, now, sid, { pu: 120 }); } }, (h) => { place(h, P, 'ORD-13'); action(h, P + 60 * MIN, 'ORD-13', 'cancel'); action(h, P + 5 * H, 'ORD-13', 'cancel'); });
S.cancelRefused = () => scenario('cancelRefused', { alloc: alloc2, onShip: (h, a, now, sid) => deliverAll(h, a, now, sid, { pu: 60, dl: 600 }) }, (h) => { place(h, P, 'ORD-14'); action(h, P + 3 * H, 'ORD-14', 'cancel'); });
S.partial = () => { let n = 0; return scenario('partial', { alloc: alloc2, reserveFail: (h, a, it) => (it.sku === 'C' && n++ < 1 ? { code: 503, reason: 'unavailable', retryable: true } : null), onShip: (h, a, now, sid) => deliverAll(h, a, now, sid) }, (h) => place(h, P, 'ORD-15')); };
S.unknown = () => { let n = 0; return scenario('unknown', { alloc: alloc2, fault: (h, e) => (e.op === 'charge' && n++ < 1 ? { commit: true, result: { status: 'unknown' } } : null), onShip: (h, a, now, sid) => deliverAll(h, a, now, sid) }, (h) => place(h, P, 'ORD-16')); };
S.rename = () => {
  const files = makeFiles(API);
  const b = JSON.parse(files['api/billing.schema.json']);
  const ch = b.ops.charge.args; ch.properties.amountCents = ch.properties.amountMinor; delete ch.properties.amountMinor; ch.required = ch.required.map((r) => (r === 'amountMinor' ? 'amountCents' : r));
  files['api/billing.schema.json'] = JSON.stringify(b);
  return scenario('rename', { alloc: alloc2, onShip: (h, a, now, sid) => deliverAll(h, a, now, sid) }, (h) => place(h, P, 'ORD-17'), { files });
};
S.migration = () => scenario('migration', { alloc: alloc2, onShip: (h, a, now, sid) => deliverAll(h, a, now, sid) }, (h) => {
  const oid = 'ORD-50';
  h.tables['orders.orders'].push({ orderId: oid, customerId: 'C1', status: 'processing', placedAt: iso(P - 2 * H), currency: 'EUR', items: [{ sku: 'A', qty: 2 }, { sku: 'C', qty: 1 }, { sku: 'B', qty: 1 }], totalMinor: 3194 });
  h.tables['orders.fulfilments'].push({ fulfilmentId: oid + '-F1', orderId: oid, location: 'AMS', items: [{ sku: 'A', qty: 2 }, { sku: 'C', qty: 1 }], amountMinor: 2594, status: 'processing' });
  h.tables['orders.fulfilments'].push({ fulfilmentId: oid + '-F2', orderId: oid, location: 'RTM', items: [{ sku: 'B', qty: 1 }], amountMinor: 645, status: 'processing' });
  h.tables['inventory.reservations'].push({ reservationId: 'RX1', orderId: oid, fulfilmentId: oid + '-F1', location: 'AMS', sku: 'A', qty: 2, status: 'active' }, { reservationId: 'RX2', orderId: oid, fulfilmentId: oid + '-F1', location: 'AMS', sku: 'C', qty: 1, status: 'active' });
  h.tables['billing.charges'].push({ chargeId: 'CX1', orderId: oid, fulfilmentId: oid + '-F1', customerId: 'C1', amountMinor: 2594, currency: 'EUR', refundedMinor: 0 });
  h.tables['carrier.shipments'].push({ shipmentId: 'SX1', orderId: oid, fulfilmentId: oid + '-F1', location: 'AMS', carrier: 'PostNL', status: 'created', ref: null });
  h.tables['inventory.reservations'].push({ reservationId: 'RX3', orderId: oid, fulfilmentId: oid + '-F2', location: 'RTM', sku: 'B', qty: 1, status: 'active' });
  h.migration(P, { orderId: oid, records: {}, messages: [] });
  // pre-go-live shipment: carrier message without ref
  h.inbound(P + 3 * H, 'message.received', { carrier: 'PostNL', code: 'PU', shipmentId: 'SX1', fulfilmentRef: ' ord-50-f1', reportedAt: iso(P + 3 * H) }, 'carrier');
  h.inbound(P + 6 * H, 'message.received', { carrier: 'PostNL', code: 'DL', shipmentId: 'SX1', fulfilmentRef: 'ORD-50-F1', reportedAt: iso(P + 6 * H) }, 'carrier');
});

for (const [k, f] of Object.entries(S)) if (!which || which === k) f();

