// Re-run every scenario and check output-level invariants on all solver outputs.
import * as fs from 'node:fs';
const API = new URL('../b1o-e8-1/api', import.meta.url).pathname;
const schemas = Object.fromEntries(fs.readdirSync(API).map((f) => { const j = JSON.parse(fs.readFileSync(API + '/' + f)); return [j.system, j]; }));
function check(v, s, p, errs) {
  if (!s) return;
  const types = Array.isArray(s.type) ? s.type : s.type ? [s.type] : [];
  const tOf = (x) => (x === null ? 'null' : Array.isArray(x) ? 'array' : Number.isInteger(x) ? 'integer' : typeof x);
  if (types.length && !types.some((t) => t === tOf(v) || (t === 'number' && typeof v === 'number'))) { errs.push(p + ' type ' + tOf(v)); return; }
  if (s.enum && !s.enum.includes(v)) errs.push(p + ' enum');
  if (typeof v === 'string') { if (s.maxLength != null && v.length > s.maxLength) errs.push(p + ' maxLength'); if (s.minLength != null && v.length < s.minLength) errs.push(p + ' minLength'); }
  if (typeof v === 'number') { if (s.minimum != null && v < s.minimum) errs.push(p + ' min'); if (s.maximum != null && v > s.maximum) errs.push(p + ' max'); }
  if (Array.isArray(v)) { if (s.minItems != null && v.length < s.minItems) errs.push(p + ' minItems'); if (s.maxItems != null && v.length > s.maxItems) errs.push(p + ' maxItems'); v.forEach((x, i) => check(x, s.items, p + '[' + i + ']', errs)); }
  if (v && typeof v === 'object' && !Array.isArray(v)) {
    for (const r of s.required || []) if (!(r in v)) errs.push(p + ' missing ' + r);
    for (const [k, x] of Object.entries(v)) { if (s.properties && s.properties[k]) check(x, s.properties[k], p + '.' + k, errs); else if (s.additionalProperties === false) errs.push(p + ' extra ' + k); }
  }
}
export function validateOutputs(h, name) {
  const errs = [];
  const keyArgs = {};
  const statusSets = {};
  for (const o of h.outputs) {
    const out = o.out;
    if (!out.decisions || !('subject' in out.decisions)) errs.push('subject missing');
    for (const e of out.effects) {
      const s = schemas[e.system]; const op = s && s.ops[e.op];
      if (!op) { errs.push('bad op ' + e.system + '.' + e.op); continue; }
      check(e.args, op.args, e.system + '.' + e.op, errs);
      if (op.keyed && !op.batch && !e.key) errs.push('no key ' + e.op);
      if (e.key) { const a = JSON.stringify(e.args); if (keyArgs[e.key] && keyArgs[e.key] !== a) errs.push('key reuse diff args ' + e.key); keyArgs[e.key] = a; if (e.key.length > 200) errs.push('key long'); }
      if (e.after && !out.effects.some((x) => x.key === e.after)) errs.push('after not in output');
    }
    if (JSON.stringify(out.carry).length > 64000) errs.push('carry big');
  }
  // ledger-level: each status target/status at most once, each notification once
  const seen = {};
  for (const l of h.ledger) {
